// Convert YYYY-MM-DD/local date to SIKUR day number (Mon=1 ... Fri=5)
const getSchoolDay = (dateValue = new Date()) => {
  const d = dateValue instanceof Date ? dateValue : new Date(`${dateValue}T00:00:00`);
  const jsDay = d.getDay(); // Sun=0, Mon=1 ... Sat=6
  return jsDay >= 1 && jsDay <= 5 ? jsDay : null;
};

const getTodayISO = () => {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth()+1).padStart(2,'0');
  const day = String(d.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
};

// --- REUSABLE COMPONENTS ---
const Modal = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex justify-center items-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center p-4 border-b">
          <h3 className="font-semibold text-lg text-slate-800">{title}</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <Icon name="close" />
          </button>
        </div>
        <div className="p-4 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

const Card = ({ title, value, icon, colorClass, subtitle }) => (
  <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-5 flex items-start space-x-4">
    <div className={`p-3 rounded-lg ${colorClass} bg-opacity-10`}>
      <div className={colorClass.replace('bg-', 'text-')}>{icon}</div>
    </div>
    <div>
      <p className="text-slate-500 text-sm font-medium">{title}</p>
      <h4 className="text-2xl font-bold text-slate-800 mt-1">{value}</h4>
      {subtitle && <p className="text-xs text-slate-400 mt-1">{subtitle}</p>}
    </div>
  </div>
);

const Badge = ({ children, type = 'gray' }) => {
  const types = {
    success: 'bg-emerald-100 text-emerald-800',
    warning: 'bg-amber-100 text-amber-800',
    danger: 'bg-rose-100 text-rose-800',
    primary: 'bg-blue-100 text-blue-800',
    gray: 'bg-slate-100 text-slate-800',
  };
  return <span className={`px-2 py-1 rounded-full text-xs font-medium ${types[type]}`}>{children}</span>;
};

