const App = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [currentView, setCurrentView] = useState('dashboard');
  const [data, setData] = useLocalStorage('sikur_data', INITIAL_DATA);
  const [currentUser, setCurrentUser] = useState(() => { try { return JSON.parse(sessionStorage.getItem('sikur_user') || 'null'); } catch { return null; } });
  const [cloudToken,setCloudToken]=useState(()=>sessionStorage.getItem('sikur_cloud_token')||'');
  const [syncState,setSyncState]=useState(cloudToken?'Cloud siap':'Cloud belum terhubung');
  const [isOnline,setIsOnline]=useState(()=>navigator.onLine);
  const login=(u)=>{setCurrentUser(u);sessionStorage.setItem('sikur_user',JSON.stringify(u));};
  const logout=()=>{setCurrentUser(null);sessionStorage.removeItem('sikur_user');};

  // SIKUR v4.2: sinkronisasi cloud otomatis selama sesi cloud aktif.
  useEffect(()=>{
    const onToken=(e)=>{setCloudToken(e.detail||'');setSyncState(e.detail?'Cloud tersambung':'Cloud belum terhubung');};
    const online=()=>{setIsOnline(true);setSyncState(cloudToken?'Online — siap sinkron':'Online — cloud belum terhubung');};
    const offline=()=>{setIsOnline(false);setSyncState('Offline — perubahan tetap tersimpan di perangkat');};
    window.addEventListener('sikur-cloud-token',onToken);window.addEventListener('online',online);window.addEventListener('offline',offline);
    return()=>{window.removeEventListener('sikur-cloud-token',onToken);window.removeEventListener('online',online);window.removeEventListener('offline',offline);};
  },[cloudToken]);

  useEffect(()=>{
    if(!cloudToken||!isOnline)return;
    const timer=setTimeout(async()=>{
      try{
        const cfg=JSON.parse(localStorage.getItem('sikur_cloud_cfg')||'{}');
        const base=String(cfg.url||'').replace(/\/$/,''); if(!base||!cfg.anonKey)return;
        setSyncState('Menyimpan ke cloud…');
        const r=await fetch(`${base}/rest/v1/sikur_state?on_conflict=id`,{method:'POST',headers:{'apikey':cfg.anonKey,'Authorization':`Bearer ${cloudToken}`,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({id:'main',data,updated_at:new Date().toISOString()})});
        if(!r.ok)throw new Error('sync');
        setSyncState('Tersimpan di Cloud');
      }catch{setSyncState('Gagal sinkron — data tetap aman di perangkat');}
    },1500);
    return()=>clearTimeout(timer);
  },[data,cloudToken,isOnline]);

  // Saat sesi cloud tersedia, ambil versi cloud terbaru sekali saat aplikasi dibuka.
  useEffect(()=>{
    if(!cloudToken||!isOnline)return;
    let cancelled=false;
    (async()=>{try{const cfg=JSON.parse(localStorage.getItem('sikur_cloud_cfg')||'{}');const base=String(cfg.url||'').replace(/\/$/,'');if(!base||!cfg.anonKey)return;setSyncState('Memeriksa Cloud…');const r=await fetch(`${base}/rest/v1/sikur_state?id=eq.main&select=data,updated_at`,{headers:{'apikey':cfg.anonKey,'Authorization':`Bearer ${cloudToken}`}});const j=await r.json();if(!r.ok)throw new Error();if(!cancelled&&j.length&&j[0].data){setData({...INITIAL_DATA,...j[0].data});setSyncState('Data Cloud terbaru dimuat');}else if(!cancelled)setSyncState('Cloud siap — data awal akan tersimpan otomatis');}catch{if(!cancelled)setSyncState('Cloud tidak dapat dibaca');}})();
    return()=>{cancelled=true};
  },[cloudToken]);

  // Responsive sidebar handling
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1024) setIsMobileMenuOpen(false);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: 'home', group: 'utama' },
    { id: 'guru', label: 'Data Guru', icon: 'users', group: 'master' },
    { id: 'kelas', label: 'Data Kelas', icon: 'book', group: 'master' },
    { id: 'mapel', label: 'Mata Pelajaran', icon: 'book', group: 'master' },
    { id: 'ruang', label: 'Ruang', icon: 'home', group: 'master' },
    { id: 'jam', label: 'Jam Pelajaran', icon: 'clock', group: 'master' },
    { id: 'jadwal', label: 'Jadwal Pelajaran', icon: 'calendar', group: 'akademik' },
    { id: 'beban', label: 'Beban Mengajar', icon: 'clock', group: 'akademik' },
    { id: 'agenda', label: 'Agenda Kurikulum', icon: 'calendar', group: 'akademik' },
    { id: 'absen', label: 'Guru Tidak Hadir', icon: 'userX', group: 'operasional' },
    { id: 'pengganti', label: 'Guru Pengganti', icon: 'userCheck', group: 'operasional' },
    { id: 'pengumuman', label: 'Pengumuman', icon: 'megaphone', group: 'operasional' },
    { id: 'cloud', label: 'SIKUR Cloud', icon: 'users', group: 'sistem' },
    { id: 'backup', label: 'Backup & Restore', icon: 'settings', group: 'sistem' },
    { id: 'pengaturan', label: 'Pengaturan & Cloud', icon: 'settings', group: 'sistem' },
  ];

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <DashboardView data={data} setView={setCurrentView} />;
      case 'guru': return <DataGuruView data={data} setData={setData} />;
      case 'kelas': return <DataKelasView data={data} setData={setData} />;
      case 'mapel': return <MasterSimpleView data={data} setData={setData} kind="subjects" title="Mata Pelajaran" />;
      case 'ruang': return <MasterSimpleView data={data} setData={setData} kind="rooms" title="Data Ruang" />;
      case 'jam': return <JamPelajaranView data={data} setData={setData} />;
      case 'jadwal': return <JadwalView data={data} setData={setData} />;
      case 'beban': return <BebanMengajarView data={data} />;
      case 'agenda': return <AgendaView data={data} setData={setData} />;
      case 'absen': return <GuruAbsenView data={data} setData={setData} />;
      case 'pengganti': return <GuruPenggantiView data={data} setData={setData} />;
      case 'pengumuman': return <PengumumanView />;
      case 'cloud': return <CloudView data={data} setData={setData} />;
      case 'backup': return <BackupView data={data} setData={setData} />;
      case 'pengaturan': return <SettingsView data={data} setData={setData} />;
      default: return <PlaceholderView title={navItems.find(n => n.id === currentView)?.label || currentView} />;
    }
  };

  const Sidebar = () => (
    <div className={`fixed inset-y-0 left-0 z-40 w-64 bg-slate-900 text-slate-300 transform ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out flex flex-col`}>
      <div className="h-16 flex items-center justify-between px-6 border-b border-slate-800 bg-slate-950">
        <span className="text-xl font-bold text-white tracking-wider flex items-center gap-2">
          <img src={SCHOOL_LOGO} alt="Logo SMAN 1 Karangreja" className="w-10 h-10 object-contain rounded-lg bg-white p-0.5"/>
          <span><span className="block">SIKUR</span><span className="block text-[10px] font-medium tracking-normal text-slate-400">SMAN 1 KARANGREJA</span></span>
        </span>
        <button className="lg:hidden" onClick={() => setIsMobileMenuOpen(false)}><Icon name="close" /></button>
      </div>
      
      <div className="flex-1 overflow-y-auto py-6 px-4 space-y-8 no-scrollbar">
        {['utama', 'master', 'akademik', 'operasional', 'sistem'].map(group => (
          <div key={group}>
            <p className="px-2 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">{group}</p>
            <div className="space-y-1">
              {navItems.filter(i => i.group === group).map(item => (
                <button
                  key={item.id}
                  onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                    currentView === item.id 
                      ? 'bg-blue-600/10 text-blue-400' 
                      : 'hover:bg-slate-800 hover:text-white'
                  }`}
                >
                  <Icon name={item.icon} className="w-5 h-5 opacity-80" />
                  {item.label}
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
      
      <div className="p-4 border-t border-slate-800">
        <div className="flex items-center gap-3 px-2">
          <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-sm font-bold text-white">WK</div>
          <div>
            <p className="text-sm font-medium text-white">{currentUser?.name || 'Pengguna'}</p>
            <p className="text-xs text-slate-500">{currentUser?.role || '-'}</p>
          </div>
          <button onClick={logout} className="ml-auto text-xs text-slate-400 hover:text-white">Keluar</button>
        </div>
      </div>
    </div>
  );

  if (!currentUser) return <LoginView onLogin={login} data={data} />;

  return (
    <div className="min-h-screen bg-slate-50/50 flex font-sans">
      <Sidebar />
      
      {/* Mobile overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/50 z-30 lg:hidden backdrop-blur-sm" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <div className="flex-1 lg:ml-64 flex flex-col min-w-0 transition-all duration-300">
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-4 sm:px-6 sticky top-0 z-20 shadow-sm/50">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 -ml-2 text-slate-500 hover:text-slate-700" onClick={() => setIsMobileMenuOpen(true)}>
              <Icon name="menu" />
            </button>
            <img src={SCHOOL_LOGO} alt="Logo" className="w-9 h-9 object-contain sm:hidden"/><h2 className="text-lg font-semibold text-slate-800 hidden sm:block">
              {navItems.find(n => n.id === currentView)?.label || 'Aplikasi SIKUR'}
            </h2>
          </div>
          <div className="flex items-center gap-4">
            <span className={`text-xs px-3 py-1.5 rounded-full font-medium ${!isOnline?'bg-amber-100 text-amber-700':cloudToken?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-500'}`} title={syncState}>● {syncState}</span>
            <span className="text-sm text-slate-500 hidden md:block flex items-center gap-2">
              <Icon name="clock" className="w-4 h-4" />
              {new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })} WIB
            </span>
          </div>
        </header>

        <main className="flex-1 p-4 sm:p-6 lg:p-8 overflow-x-hidden">
          {renderView()}
          <div className="mt-8 pt-4 border-t text-xs text-slate-400 flex justify-between"><span>SIKUR — SMA Negeri 1 Karangreja</span><span>Versi 4.2 Auto Sync</span></div>
        </main>
      </div>
    </div>
  );
};

export default App;